async function submitTending(event) {
  event.preventDefault();
  if (state.mutating) return;
  hideFormError();

  const question = dom.question.value.trim();
  if (!question) {
    showFormError("The material needs a question before it can resist.");
    dom.question.focus();
    return;
  }

  state.mutating = true;
  dom.tendSubmit.disabled = true;
  try {
    const data = await request("/api/tend", {
      method: "POST",
      body: {
        question,
        constraint: dom.constraint.value,
        invariant: dom.invariant.value,
        refusal: dom.refusal.value
      }
    });
    applySnapshot(data);
    state.selectedStation = data.result.station.id;
    renderAll();
    showAnswer(data.result);
    dom.question.value = "";
    updateQuestionCount();
    toast(`A new structure took the name ${data.result.structure.name}.`);
  } catch (error) {
    showFormError(error.message);
  } finally {
    state.mutating = false;
    dom.tendSubmit.disabled = false;
  }
}

function showFormError(message) {
  dom.formError.textContent = message;
  dom.formError.hidden = false;
}

function hideFormError() {
  dom.formError.hidden = true;
  dom.formError.textContent = "";
}

function showAnswer(result) {
  dom.answerCard.hidden = false;
  dom.answerText.textContent = result.answer;
  dom.answerStation.textContent = result.station.name;
  dom.answerDeltas.textContent = formatDeltas(result.deltas);
  dom.answerReceipt.textContent = `receipt ${result.event.receipt} · ${result.structure.name}`;
  dom.answerCard.style.animation = "none";
  void dom.answerCard.offsetWidth;
  dom.answerCard.style.animation = "";
}

function formatDeltas(deltas) {
  if (!deltas || deltas.length === 0) return "No measurable shift";
  return deltas.map((item) => `${item.name} ${signedPct(item.delta)}`).join(" · ");
}

async function respondToVisitor(choice, button) {
  if (state.mutating) return;
  state.mutating = true;
  const buttons = Array.from(dom.visitorBody.querySelectorAll(".visitor-choice"));
  buttons.forEach((item) => { item.disabled = true; });
  if (button) button.disabled = true;
  try {
    const data = await request("/api/respond", { method: "POST", body: { choice } });
    applySnapshot(data);
    renderAll();
    toast(truncate(data.result.answer, 240), "info", 6200);
  } catch (error) {
    toast(error.message, "error", 5200);
  } finally {
    state.mutating = false;
    buttons.forEach((item) => { item.disabled = false; });
    if (button) button.disabled = false;
  }
}

async function moveWorld() {
  if (state.mutating) return;
  state.mutating = true;
  dom.advance.disabled = true;
  try {
    const data = await request("/api/tick", { method: "POST", body: { steps: 1 } });
    applySnapshot(data);
    renderAll();
    setConnection("awake");
    toast(`Cycle ${pad(data.world.cycle)} · ${data.world.whisper}`, "info", 4800);
  } catch (error) {
    toast(error.message, "error", 5200);
  } finally {
    state.mutating = false;
    dom.advance.disabled = false;
  }
}

