function renderAll() {
  if (!state.world || !state.catalog) return;
  renderHeader();
  renderMemoryPreview();
  renderVisitor();
  renderStats();
  renderStationTabs();
  renderStationDetail();
  renderChronicle();
  renderMeta();
}

function renderHeader() {
  const world = state.world;
  const weather = world.weather || {};
  dom.cycle.textContent = pad(world.cycle);
  dom.atlasCycle.textContent = pad(world.cycle);
  dom.weatherTop.textContent = weather.name || "weather unread";
  dom.weatherName.textContent = weather.name || "Weather unread";
  dom.weatherDescription.textContent = weather.description || "The sky has not decided how to answer.";
  dom.visibilityValue.textContent = pct(weather.visibility);
  dom.pressureValue.textContent = pct(weather.pressure);
  dom.whisper.textContent = world.whisper || "The world is listening.";
  dom.atlas.setAttribute(
    "aria-label",
    `A circular living map of Tendora. Cycle ${world.cycle}. Weather: ${weather.name || "unread"}. ${world.stations.length} stations.`
  );
}

.atlas-column {
  min-width: 0;
